   371→    method build_loop_phi_node($loop_node, $initial_value, $loop_value = undef) {
   372→        # Loop phi starts with control and initial value
   373→        # Loop value added later (lazy phi pattern)
   374→        my @inputs = ($loop_node->id, $initial_value);
   375→        push @inputs, $loop_value if defined $loop_value;
   376→
   377→        my $empty_attrs = {};
   378→        my $node_id = $self->next_node_id();
   379→        my $phi = Chalk::IR::Node->new(
   380→            id => $node_id,
   381→            op => 'Phi',
   382→            inputs => \@inputs,
   383→            attributes => $empty_attrs
   384→        );
   385→        $graph->add_node($phi);
   386→        return $phi;
