   389→    # Function call nodes
   390→    method build_call_node($function_name, @arg_nodes) {
   391→        # Call: control, memory, arguments...
   392→        # For now, use current_control for both control and memory
   393→        my $attributes = { function => $function_name };
   394→        my $node_id = $self->next_node_id();
   395→        my $call = Chalk::IR::Node->new(
   396→            id => $node_id,
   397→            op => 'Call',
   398→            inputs => [$current_control, $current_control, map { $_->id } @arg_nodes],
   399→            attributes => $attributes
   400→        );
   401→        $graph->add_node($call);
   402→        return $call;
   403→    }
