     7→class Chalk::IR::Validator {
     8→    use Chalk::IR::Node;
     9→    use Chalk::IR::Graph;
    10→
    11→    # Main validation entry point - runs all validators
    12→    method validate_all($graph) {
    13→        my @all_errors = ();
    14→
    15→        # Run each validator and collect errors
    16→        push @all_errors, $self->validate_cfg($graph);
    17→        push @all_errors, $self->validate_single_assignment($graph);
    18→        push @all_errors, $self->validate_dominance($graph);
    19→        push @all_errors, $self->validate_phi_placement($graph);
    20→        push @all_errors, $self->validate_loop_structure($graph);
    21→
    22→        my $success = scalar( @all_errors ) == 0 ? 1 : 0;
    23→        return ($success, \@all_errors);
    24→    }
    25→
    26→    # Validate Control Flow Graph structure
    27→    method validate_cfg($graph) {
    28→        my @errors = ();
    29→
    30→        # Check: Single Start node exists
    31→        my $start_count = 0;
    32→        my $start_id = undef;
    33→        my $nodes = $graph->nodes;
    34→
    35→        for my $node_id (keys( $nodes->%* )) {
    36→            my $node = $nodes->{$node_id};
    37→            if ($node->op eq 'Start') {
    38→                $start_count++;
    39→                $start_id = $node_id;
    40→            }
    41→        }
    42→
    43→        if ($start_count == 0) {
    44→            push @errors, "CFG validation failed: No Start node found in graph";
    45→        }
    46→        elsif ($start_count > 1) {
    47→            push @errors, "CFG validation failed: Multiple Start nodes found ($start_count), expected exactly 1";
    48→        }
    49→
    50→        # Check: At least one Return node exists
    51→        my $return_count = 0;
    52→        for my $node_id (keys( $nodes->%* )) {
    53→            my $node = $nodes->{$node_id};
    54→            if ($node->op eq 'Return') {
    55→                $return_count++;
    56→            }
    57→        }
    58→
    59→        if ($return_count == 0) {
    60→            push @errors, "CFG validation failed: No Return node found in graph";
    61→        }
    62→
    63→        # Check: All nodes reachable from Start (BFS traversal)
    64→        if (defined($start_id)) {
    65→            # Build successor map once for O(n+e) BFS instead of O(n²)
    66→            # In Sea of Nodes, inputs point TO this node FROM others,
    67→            # so we need to reverse the edges to get successors
    68→            my %successors = ();
    69→            for my $node_id (keys( $nodes->%* )) {
    70→                $successors{$node_id} = [];
    71→            }
    72→            for my $node_id (keys( $nodes->%* )) {
    73→                my $node = $nodes->{$node_id};
    74→                for my $input_id ($node->inputs->@*) {
    75→                    if (exists($nodes->{$input_id})) {
    76→                        push $successors{$input_id}->@*, $node_id;
    77→                    }
    78→                }
    79→            }
    80→
    81→            # BFS using successor map
    82→            my %reachable = ();
    83→            my @queue = ($start_id);
    84→            $reachable{$start_id} = 1;
    85→
    86→            while (scalar( @queue ) > 0) {
    87→                my $current_id = shift @queue;
    88→
    89→                # Follow all successors (nodes that depend on current node)
    90→                for my $successor_id ($successors{$current_id}->@*) {
    91→                    next if exists($reachable{$successor_id});
    92→                    $reachable{$successor_id} = 1;
    93→                    push @queue, $successor_id;
    94→                }
    95→            }
    96→
    97→            # Report unreachable nodes (except Constants which are data-only)
    98→            for my $node_id (keys( $nodes->%* )) {
    99→                if (not(exists($reachable{$node_id}))) {
   100→                    my $node = $nodes->{$node_id};
   101→                    # Constants are data-only nodes and don't need control flow reachability
   102→                    if ($node->op ne 'Constant') {
   103→                        push @errors, "CFG validation failed: Node $node_id is not reachable from Start node";
   104→                    }
   105→                }
   106→            }
   107→        }
   108→
   109→        return @errors;
   110→    }
   111→
   112→    # Validate SSA single assignment property
   113→    method validate_single_assignment($graph) {
   114→        my @errors = ();
   115→        my %assignments = ();  # variable_name => [node_ids]
   116→
   117→        my $nodes = $graph->nodes;
   118→
   119→        # Collect all Store nodes (variable assignments)
   120→        for my $node_id (keys( $nodes->%* )) {
   121→            my $node = $nodes->{$node_id};
   122→            if ($node->op eq 'Store') {
   123→                my $var_name = $node->attributes->{variable};
   124→                if (defined($var_name)) {
   125→                    $assignments{$var_name} //= [];
   126→                    push $assignments{$var_name}->@*, $node_id;
   127→                }
   128→            }
   129→        }
   130→
   131→        # Check for multiple assignments to same variable
   132→        for my $var_name (keys( %assignments )) {
   133→            my $assign_list = $assignments{$var_name};
   134→            if (scalar( $assign_list->@* ) > 1) {
   135→                my $node_list = join(', ', $assign_list->@*);
   136→                push @errors, "SSA violation: Variable $var_name is assigned more than once (in nodes: $node_list)";
   137→            }
   138→        }
   139→
   140→        return @errors;
   141→    }
   142→
   143→    # Compute dominance tree using Cooper/Harvey/Kennedy algorithm
   144→    method compute_dominance_tree($graph) {
   145→        my $nodes = $graph->nodes;
   146→        my %dom = ();  # node_id => immediate_dominator_id
   147→
   148→        # Find Start node
   149→        my $start_id = undef;
   150→        for my $node_id (keys( $nodes->%* )) {
   151→            my $node = $nodes->{$node_id};
   152→            if ($node->op eq 'Start') {
   153→                $start_id = $node_id;
   154→                last;
   155→            }
   156→        }
   157→
   158→        return \%dom unless defined($start_id);
   159→
   160→        # Compute node depths for _intersect heuristic
   161→        my $depth_map = $self->_compute_node_depths($graph);
   162→
   163→        # Build reverse graph (predecessors)
   164→        my %preds = ();  # node_id => [predecessor_ids]
   165→        for my $node_id (keys( $nodes->%* )) {
   166→            $preds{$node_id} = [];
   167→        }
   168→
   169→        for my $node_id (keys( $nodes->%* )) {
   170→            my $node = $nodes->{$node_id};
   171→            for my $input_id ($node->inputs->@*) {
   172→                if (exists($nodes->{$input_id})) {
   173→                    push $preds{$node_id}->@*, $input_id;
   174→                }
   175→            }
   176→        }
   177→
   178→        # Initialize: Start dominates itself
   179→        $dom{$start_id} = $start_id;
   180→
   181→        # Iterative dataflow until convergence
   182→        my $changed = 1;
   183→        my $max_iterations = scalar( keys( $nodes->%* ) ) * 2;
   184→        my $iterations = 0;
   185→
   186→        while ($changed) {
   187→            if ($iterations > $max_iterations) {
   188→                last;
   189→            }
   190→            $changed = 0;
   191→            $iterations++;
   192→
   193→            for my $node_id (keys( $nodes->%* )) {
   194→                next if $node_id eq $start_id;
   195→
   196→                my @pred_list = $preds{$node_id}->@*;
   197→                next if scalar( @pred_list ) == 0;
   198→
   199→                # Find first processed predecessor
   200→                my $new_idom = undef;
   201→                for my $pred_id (@pred_list) {
   202→                    if (exists($dom{$pred_id})) {
   203→                        $new_idom = $pred_id;
   204→                        last;
   205→                    }
   206→                }
   207→
   208→                next unless defined($new_idom);
   209→
   210→                # Intersect with all other predecessors
   211→                for my $pred_id (@pred_list) {
   212→                    next if $pred_id eq $new_idom;
   213→                    next unless exists($dom{$pred_id});
   214→
   215→                    $new_idom = $self->_intersect(\%dom, $pred_id, $new_idom, $depth_map);
   216→                }
   217→
   218→                # Update if changed
   219→                if (not(exists($dom{$node_id}))) {
   220→                    $dom{$node_id} = $new_idom;
   221→                    $changed = 1;
   222→                }
   223→                elsif ($dom{$node_id} ne $new_idom) {
   224→                    $dom{$node_id} = $new_idom;
   225→                    $changed = 1;
   226→                }
   227→            }
   228→        }
   229→
   230→        return \%dom;
   231→    }
   232→
   233→    # Helper: Find intersection of two nodes in dominance tree
   234→    method _intersect($dom, $b1, $b2, $depth_map = undef) {
   235→        my $finger1 = $b1;
   236→        my $finger2 = $b2;
   237→
   238→        while ($finger1 ne $finger2) {
   239→            # Move up dominance tree
   240→            while ($self->_node_depth($finger1, $depth_map) > $self->_node_depth($finger2, $depth_map)) {
   241→                $finger1 = $dom->{$finger1};
   242→                last unless defined($finger1);
   243→            }
   244→            last unless defined($finger1);
   245→
   246→            while ($self->_node_depth($finger2, $depth_map) > $self->_node_depth($finger1, $depth_map)) {
   247→                $finger2 = $dom->{$finger2};
   248→                last unless defined($finger2);
   249→            }
   250→            last unless defined($finger2);
   251→
   252→            if ($finger1 eq $finger2) {
   253→                last;
   254→            }
   255→
   256→            # Both at same depth, move up together
   257→            $finger1 = $dom->{$finger1};
   258→            $finger2 = $dom->{$finger2};
   259→
   260→            last unless defined($finger1);
   261→            last unless defined($finger2);
   262→        }
   263→
   264→        return $finger1;
   265→    }
   266→
   267→    # Helper: Compute CFG depth for all nodes via BFS from Start
   268→    # Returns hashref mapping node_id => depth
   269→    method _compute_node_depths($graph) {
   270→        my $nodes = $graph->nodes;
   271→        my %depths = ();
   272→
   273→        # Find Start node
   274→        my $start_id = undef;
   275→        for my $node_id (keys( $nodes->%* )) {
   276→            my $node = $nodes->{$node_id};
   277→            if ($node->op eq 'Start') {
   278→                $start_id = $node_id;
   279→                last;
   280→            }
   281→        }
   282→
   283→        return \%depths unless defined($start_id);
   284→
   285→        # BFS to compute depths
   286→        my @queue = ($start_id);
   287→        $depths{$start_id} = 0;
   288→
   289→        while (scalar( @queue ) > 0) {
   290→            my $current_id = shift @queue;
   291→            my $current_depth = $depths{$current_id};
   292→
   293→            # Find all nodes that have current_id as input
   294→            for my $node_id (keys( $nodes->%* )) {
   295→                next if exists($depths{$node_id});
   296→                my $node = $nodes->{$node_id};
   297→
   298→                for my $input_id ($node->inputs->@*) {
   299→                    if ($input_id eq $current_id) {
   300→                        $depths{$node_id} = $current_depth + 1;
   301→                        push @queue, $node_id;
   302→                        last;
   303→                    }
   304→                }
   305→            }
   306→        }
   307→
   308→        return \%depths;
   309→    }
   310→
   311→    # Helper: Get node depth from cached depth map
   312→    # Falls back to parsing node_id for backward compatibility
   313→    method _node_depth($node_id, $depth_map = undef) {
   314→        return 0 unless defined($node_id);
   315→
   316→        # Use cached depth if available
   317→        if (defined($depth_map) && exists($depth_map->{$node_id})) {
   318→            return $depth_map->{$node_id};
   319→        }
   320→
   321→        # Fallback: parse node_id (e.g., "node_123" => 123)
   322→        # This is a heuristic and may not reflect true CFG depth
   323→        my $pattern = qr/node_(\d+)/;
   324→        if ($node_id =~ $pattern) {
   325→            return $1;
   326→        }
   327→        return 0;
   328→    }
   329→
   330→    # Validate dominance property: definitions dominate uses
   331→    method validate_dominance($graph) {
   332→        my @errors = ();
   333→
   334→        my $dom_tree = $self->compute_dominance_tree($graph);
   335→        my $nodes = $graph->nodes;
   336→
   337→        # Check each Load node: its Store must exist and be valid
   338→        for my $node_id (keys( $nodes->%* )) {
   339→            my $node = $nodes->{$node_id};
   340→            if ($node->op eq 'Load') {
   341→                my $var_name = $node->attributes->{variable};
   342→                my $store_id = $node->attributes->{store_id};
   343→
   344→                if (defined($store_id)) {
   345→                    if (defined($var_name)) {
   346→                        # Check if store exists
   347→                        if (not(exists($nodes->{$store_id}))) {
   348→                            push @errors, "Dominance violation: Load of $var_name in $node_id references non-existent Store $store_id";
   349→                            next;
   350→                        }
   351→
   352→                        my $store_node = $nodes->{$store_id};
   353→                        if ($store_node->op ne 'Store') {
   354→                            push @errors, "Dominance violation: Load of $var_name in $node_id references $store_id which is not a Store node";
   355→                            next;
   356→                        }
   357→
   358→                        # For graphs with control flow (Region nodes), check strict dominance
   359→                        # For linear graphs (Chapters 1-4), the store_id reference is sufficient
   360→                        my $has_control_flow = $self->_has_control_flow($graph);
   361→
   362→                        if ($has_control_flow) {
   363→                            my $is_dominated = $self->_dominates($dom_tree, $store_id, $node_id);
   364→                            if (not($is_dominated)) {
   365→                                push @errors, "Dominance violation: Load of $var_name in $node_id is not dominated by its Store in $store_id";
   366→                            }
   367→                        }
   368→                    }
   369→                }
   370→            }
   371→        }
   372→
   373→        return @errors;
   374→    }
   375→
   376→    # Helper: Check if graph has control flow (Region/If nodes)
   377→    method _has_control_flow($graph) {
   378→        my $nodes = $graph->nodes;
   379→        for my $node_id (keys( $nodes->%* )) {
   380→            my $node = $nodes->{$node_id};
   381→            if ($node->op eq 'Region' || $node->op eq 'If') {
   382→                return 1;
   383→            }
   384→        }
   385→        return 0;
   386→    }
   387→
   388→    # Helper: Check if dominator_id dominates target_id
   389→    method _dominates($dom_tree, $dominator_id, $target_id) {
   390→        return 1 if $dominator_id eq $target_id;
   391→
   392→        # Walk up dominance tree from target
   393→        my $current = $target_id;
   394→        my $max_steps = 100;
   395→        my $steps = 0;
   396→
   397→        while (defined($current)) {
   398→            if ($steps > $max_steps) {
   399→                last;
   400→            }
   401→            $steps++;
   402→
   403→            if (exists($dom_tree->{$current})) {
   404→                $current = $dom_tree->{$current};
   405→                if (defined($current)) {
   406→                    if ($current eq $dominator_id) {
   407→                        return 1;
   408→                    }
   409→                }
   410→            }
   411→            else {
   412→                last;
   413→            }
   414→        }
   415→
   416→        return 0;
   417→    }
   418→
   419→    # Validate phi node placement (prepare for Chapter 5)
   420→    method validate_phi_placement($graph) {
   421→        my @errors = ();
   422→
   423→        my $nodes = $graph->nodes;
   424→
   425→        # Check each Phi node
   426→        for my $node_id (keys( $nodes->%* )) {
   427→            my $node = $nodes->{$node_id};
   428→            next unless $node->op eq 'Phi';
   429→
   430→            # Phi must be at a Region (control flow merge point)
   431→            my $phi_inputs = $node->inputs;
   432→            if (scalar( $phi_inputs->@* ) == 0) {
   433→                push @errors, "Phi node $node_id has no control input (must connect to Region)";
   434→                next;
   435→            }
   436→
   437→            my $region_id = $phi_inputs->[0];
   438→            if (exists($nodes->{$region_id})) {
   439→                my $region_node = $nodes->{$region_id};
   440→                if ($region_node->op ne 'Region' && $region_node->op ne 'Loop') {
   441→                    push @errors, "Phi node $node_id is not at a Region/Loop merge point (control input is " . $region_node->op . ")";
   442→                }
   443→                else {
   444→                    # Count region/loop predecessors
   445→                    my $region_preds = $region_node->inputs;
   446→                    my $expected_alternatives = scalar( $region_preds->@* );
   447→
   448→                    # Count phi alternatives from standardized inputs array
   449→                    # Phi nodes use inputs array: inputs => [ctrl, val1, val2, ...]
   450→                    # This is the standardized representation as per GitHub Issue #80
   451→                    my $phi_inputs = $node->inputs;
   452→                    my $actual_alternatives = scalar( $phi_inputs->@* ) - 1;  # Subtract control input
   453→
   454→                    if ($actual_alternatives != $expected_alternatives) {
   455→                        push @errors, "Phi node $node_id in node $region_id expects $expected_alternatives value inputs ($expected_alternatives predecessors) but has $actual_alternatives";
   456→                    }
   457→                }
   458→            }
   459→            else {
   460→                push @errors, "Phi node $node_id references non-existent Region $region_id";
   461→            }
   462→        }
   463→
   464→        return @errors;
   465→    }
   466→
   467→    # Validate Loop node structure and semantics
   468→    method validate_loop_structure($graph) {
   469→        my @errors = ();
   470→
   471→        my $nodes = $graph->nodes;
   472→
   473→        # Check each Loop node
   474→        for my $node_id (keys( $nodes->%* )) {
   475→            my $node = $nodes->{$node_id};
   476→            next unless $node->op eq 'Loop';
   477→
   478→            # Loop must have exactly 2 inputs: entry control + backedge
   479→            my $loop_inputs = $node->inputs;
   480→            my $num_inputs = scalar( $loop_inputs->@* );
   481→
   482→            if ($num_inputs < 1) {
   483→                push @errors, "Loop node $node_id has no entry control input";
   484→            }
   485→            elsif ($num_inputs == 1) {
   486→                # Loop with only entry, no backedge - might be under construction
   487→                # This is valid during IR building (lazy phi pattern)
   488→            }
   489→            elsif ($num_inputs == 2) {
   490→                # Valid: entry + backedge
   491→            }
   492→            elsif ($num_inputs > 2) {
   493→                push @errors, "Loop node $node_id has $num_inputs inputs, expected exactly 2 (entry + backedge)";
   494→            }
   495→
   496→            # Check for unreachable loops (no exit path)
   497→            # A loop should have an If node as successor that provides exit
   498→            if ($num_inputs == 2) {
   499→                my $has_exit = $self->_loop_has_exit($graph, $node_id);
   500→                unless ($has_exit) {
   501→                    # Note: Infinite loops are valid (e.g., while(1) { ... })
   502→                    # This is informational, not an error
   503→                    # push @errors, "Loop node $node_id may be infinite (no exit condition detected)";
   504→                }
   505→            }
   506→        }
   507→
   508→        return @errors;
   509→    }
   510→
   511→    # Helper: Check if loop has an exit path (If node with false branch)
   512→    method _loop_has_exit($graph, $loop_id) {
   513→        my $nodes = $graph->nodes;
   514→
   515→        # Look for If nodes that use the loop as control
   516→        for my $node_id (keys( $nodes->%* )) {
   517→            my $node = $nodes->{$node_id};
   518→            if ($node->op eq 'If') {
   519→                my $inputs = $node->inputs;
   520→                if (scalar( $inputs->@* ) > 0 && $inputs->[0] eq $loop_id) {
   521→                    # Found If node controlled by this loop
   522→                    # If has both true and false projections - exit exists
   523→                    return 1;
   524→                }
   525→            }
   526→        }
   527→
   528→        return 0;
   529→    }
   530→}
   531→
   532→1;
   533→
   534→

