    my $hash_exists = Chalk::IR::Node->new(
        id => 'node_6',
        op => 'HashExists',
        inputs => ['node_0', 'node_4', 'node_2'],  # Control, hash, key
        attributes => {
            hash => { op => 'NodeRef', node_id => 'node_4' },
            key => { op => 'NodeRef', node_id => 'node_2' }
        }
    );
    $graph->add_node($hash_exists);

