        id => 'node_7',
        op => 'HashKeys',
        inputs => ['node_0', 'node_4'],  # Control, hash
        attributes => {
            hash => { op => 'NodeRef', node_id => 'node_4' }
        }
    );
    $graph->add_node($hash_keys);

