                    push @errors, "StrSubstr node $node_id 'length' NodeRef missing node_id";
                }
                else {
                    # Verify length node exists
                    my $length_id = $attrs->{length}{node_id};
                    if (!exists($nodes->{$length_id})) {
                        push @errors, "StrSubstr node $node_id references non-existent length node $length_id";
                    }
                }
            }
        }

        return @errors;
    }
}

