            elsif ($op eq 'HashSet') {
                my $attrs = $node->attributes;

                # HashSet must have 'hash' attribute
                if (!exists($attrs->{hash})) {
                    push @errors, "HashSet node $node_id missing required 'hash' attribute";
                }
